def comps(g,val=0,conn=8):
    h,w=len(g),len(g[0]); seen=set(); out=[]
    for r in range(h):
        for c in range(w):
            if g[r][c]==val and (r,c) not in seen:
                st=[(r,c)]; seen.add((r,c)); comp=[]
                while st:
                    a,b=st.pop(); comp.append((a,b))
                    for dr in range(-1,2):
                        for dc in range(-1,2):
                            if dr==dc==0: continue
                            if conn==4 and abs(dr)+abs(dc)!=1: continue
                            x,y=a+dr,b+dc
                            if 0<=x<h and 0<=y<w and g[x][y]==val and (x,y) not in seen:
                                seen.add((x,y)); st.append((x,y))
                out.append(comp)
    return out
