def f2(g):
    from collections import Counter
    cnt=Counter(x for row in g for x in row); bg=cnt.most_common(1)[0][0]
    seedcells=[(r,c) for r in range(len(g)) for c in range(len(g[0])) if g[r][c] not in (0,bg)]
    P={(r-min(a for a,b in seedcells),c-min(b for a,b in seedcells)) for r,c in seedcells}
    seed=g[seedcells[0][0]][seedcells[0][1]]
    g=[row[:] for row in g]
    for r,c in matchesP(g,P):
        for dr,dc in P: g[r+dr][c+dc]=seed
    return g
